TableSelectDialog.items:
{
    path: '/PurchaseContracts',
    parameters: {
      $filter: 'Status eq \'Approved\' or Status eq \'Finished\''
    },
    sorter: {
      path: 'Code',
      descending: false
    }
  }

ObjectNumber.number:
{
        path: 'TotalVolume',
        type: 'sap.ui.model.type.Float',
        formatOptions: {
          decimals: 3,
          decimalSeparator: ',',
          groupingEnabled: true,
          groupingSeparator: '.'
        }
      }

{
        path: 'AvaiableVolume',
        type: 'sap.ui.model.type.Float',
        formatOptions: {
          decimals: 3,
          decimalSeparator: ',',
          groupingEnabled: true,
          groupingSeparator: '.'
        }
      }
